"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33792"],{34846(e){e.exports=JSON.parse('{"id":"V4-034","slug":"balance-of-payments","term":"Balance of Payments","also_known_as":[],"difficulty":"Advanced","definition":"The balance of payments is a record of all economic transactions between a country\u2019s residents and the rest of the world over a period, including trade, income, transfers and investment flows.","explanation":["The balance of payments has three main parts. The current account records trade in goods and services, income such as wages, interest and dividends, and transfers such as remittances and foreign aid. The capital account records certain transfers of assets, such as debt forgiveness. The financial account records investment flows, such as purchases of foreign shares, bonds, companies and property, as well as changes in central bank reserves.","In principle, the accounts must balance overall. If a country buys more from abroad than it sells, running a current account deficit, it must finance this by borrowing from abroad or selling assets to foreigners, which appears as a surplus in the financial account.","For example, a country with a current account deficit of 50 billion might attract 50 billion of foreign investment into its shares, bonds and property. In practice, a statistical discrepancy item captures measurement errors.","The balance of payments helps economists judge a country\u2019s external position. Persistent large current account deficits financed by short-term borrowing can make a country vulnerable to sudden outflows of capital and currency crises."],"note":"","total":1725,"prev":{"slug":"bailout","term":"Bailout"},"next":{"slug":"balance-sheet","term":"Balance Sheet"}}')}}]);